    public virtual float GetDistanceAttenuation(float lightVectorLength, float lightInvSquareRadius)
    {
        float d2 = lightVectorLength * lightVectorLength;
        float attenuation = 1.0f / (max(d2, 0.01f * 0.01f));
        attenuation *= SmoothDistanceAttenuation(d2, lightInvSquareRadius);
        return attenuation;
    }

    public virtual float GetAngularAttenuation(float3 lightVector, float3 lightDirection, float lightAngleScale, float lightAngleOffset)
