        // float lightAngleOffset = -cosOuter * angleScale;
        float cd = dot(lightDirection, lightVector);
        float attenuation = saturate(cd * lightAngleScale + lightAngleOffset);
        // smooth the transition
        attenuation *= attenuation;
        return attenuation;
    }
